B_LABEL=$(kubectl get pod backend -n network-demo -o jsonpath='{.metadata.labels.role}')
D_LABEL=$(kubectl get pod database -n network-demo -o jsonpath='{.metadata.labels.role}')

if [ "$F_LABEL" != "frontend" ] || [ "$B_LABEL" != "backend" ] || [ "$D_LABEL" != "db" ]; then
  echo "FAIL: Pod labels are incorrect: frontend=$F_LABEL (exp: frontend), backend=$B_LABEL (exp: backend), database=$D_LABEL (exp: db)"
  exit 1
fi
echo "PASS: Question 07A passed! Pod labels updated to satisfy NetworkPolicy."
