cat << 'EOF' > "${LAB_DIR}/q16a-resource-quota/question.md"
# Question 16A: Pod Limits from ResourceQuota

Namespace `prod` has a ResourceQuota configured.

Tasks:
1. Inspect the ResourceQuota in namespace `prod`.
2. Create a Pod named `resource-pod` in namespace `prod` with image `nginx:latest`.
3. Set CPU and Memory limits to **exactly half** of the ResourceQuota limits.
4. Set requests to `100m` CPU and `128Mi` memory.
EOF
cat << 'EOF' > "${LAB_DIR}/q16a-resource-quota/setup.sh"
#!/bin/bash
set -e
kubectl create ns prod --dry-run=client -o yaml | kubectl apply -f -
cat << 'EOF' | kubectl apply -f -
apiVersion: v1
kind: ResourceQuota
metadata:
  name: compute-quota
  namespace: prod
spec:
  hard:
    limits.cpu: "2"
    limits.memory: "4Gi"
EOF
kubectl delete pod resource-pod -n prod --ignore-not-found
echo "Scenario 21 ready. Solve it now!"
EOF
chmod +x "${LAB_DIR}/q16a-resource-quota/setup.sh"
cat << 'EOF' > "${LAB_DIR}/q16a-resource-quota/check.sh"
#!/bin/bash
set -e
if ! kubectl get pod resource-pod -n prod &>/dev/null; then
  echo "FAIL: Pod resource-pod not found in namespace prod"
  exit 1
fi
CPU_LIM=$(kubectl get pod resource-pod -n prod -o jsonpath='{.spec.containers[0].resources.limits.cpu}')
MEM_LIM=$(kubectl get pod resource-pod -n prod -o jsonpath='{.spec.containers[0].resources.limits.memory}')

if [ "$CPU_LIM" != "1" ] && [ "$CPU_LIM" != "1000m" ]; then
  echo "FAIL: CPU limit is $CPU_LIM (expected 1 or 1000m)"
  exit 1
fi
if [ "$MEM_LIM" != "2Gi" ]; then
  echo "FAIL: Memory limit is $MEM_LIM (expected 2Gi)"
  exit 1
fi
echo "PASS: Question 16A passed! ResourceQuota limits calculated and applied."
EOF
chmod +x "${LAB_DIR}/q16a-resource-quota/check.sh"
cat << 'EOF' > "${LAB_DIR}/q16a-resource-quota/solve.sh"
#!/bin/bash
echo "Check quota: kubectl describe quota compute-quota -n prod"
echo "Create pod with requests: cpu=100m, memory=128Mi and limits: cpu=1, memory=2Gi"
EOF
chmod +x "${LAB_DIR}/q16a-resource-quota/solve.sh"
cat << 'EOF' > "${LAB_DIR}/q16a-resource-quota/undo.sh"
#!/bin/bash
kubectl delete ns prod --ignore-not-found
echo "Scenario 21 cleaned."
