echo "Configuring Scenario 22: Multi-Container Pod (Sidecar Logging Pattern)..."
mkdir -p "${LAB_DIR}/q17-sidecar-logging"
cat << 'EOF' > "${LAB_DIR}/q17-sidecar-logging/question.md"
# Question 17: Multi-Container Sidecar Logging

In namespace `logging`, deploy a Pod named `multi-app`:
1. Container 1 named `app` (image: `busybox:latest`) writes timestamps to `/var/log/access.log` every 1s:
   `while true; do date >> /var/log/access.log; sleep 1; done`.
2. Container 2 named `sidecar` (image: `busybox:latest`) reads the stream:
   `tail -n+1 -F /var/log/access.log`.
3. Both containers share an `emptyDir` volume mounted at `/var/log`.
EOF
cat << 'EOF' > "${LAB_DIR}/q17-sidecar-logging/setup.sh"
#!/bin/bash
set -e
kubectl create ns logging --dry-run=client -o yaml | kubectl apply -f -
kubectl delete pod multi-app -n logging --ignore-not-found
echo "Scenario 22 ready. Solve it now!"
EOF
chmod +x "${LAB_DIR}/q17-sidecar-logging/setup.sh"
cat << 'EOF' > "${LAB_DIR}/q17-sidecar-logging/check.sh"
#!/bin/bash
set -e
if ! kubectl get pod multi-app -n logging &>/dev/null; then
  echo "FAIL: Pod multi-app not found in namespace logging"
  exit 1
fi
C_COUNT=$(kubectl get pod multi-app -n logging -o jsonpath='{range .spec.containers[*]}{.name}{" "}{end}' | wc -w)
if [ "$C_COUNT" != "2" ]; then
  echo "FAIL: Pod multi-app has $C_COUNT containers (exp 2)"
  exit 1
fi
if ! kubectl logs multi-app -c sidecar -n logging 2>/dev/null | grep -q "UTC"; then
  echo "FAIL: sidecar container is not streaming logs from shared volume"
  exit 1
fi
echo "PASS: Question 17 passed! Multi-container sidecar streaming logs successfully."
EOF
chmod +x "${LAB_DIR}/q17-sidecar-logging/check.sh"
cat << 'EOF' > "${LAB_DIR}/q17-sidecar-logging/solve.sh"
#!/bin/bash
echo "Create Pod with 2 containers sharing an emptyDir volume mounted at /var/log"
EOF
