# Question 18: Observability & Log Extraction

Tasks:
1. Identify the pod consuming the most CPU in namespace `monitoring`. Save its name to `/opt/high_cpu_pod.txt`.
2. Pod `faulty-backend` in namespace `default` is malfunctioning. Extract all lines containing `[ERROR]` and save to `/opt/errors.log`.
EOF
cat << 'EOF' > "${LAB_DIR}/q18-observability-logs/setup.sh"
#!/bin/bash
set -e
kubectl create ns monitoring --dry-run=client -o yaml | kubectl apply -f -
kubectl run low-pod --image=busybox -n monitoring -- sleep 3600
kubectl run high-pod --image=busybox -n monitoring -- sh -c 'yes > /dev/null' 2>/dev/null || true
cat << 'EOF' | kubectl apply -f -
apiVersion: v1
kind: Pod
metadata:
  name: faulty-backend
  namespace: default
spec:
  containers:
  - name: app
    image: busybox
    command: ["sh", "-c", "echo '[INFO] Server started'; echo '[ERROR] DB Connection Failed'; echo '[ERROR] Timeout'; sleep 3600"]
EOF
rm -f /opt/high_cpu_pod.txt /opt/errors.log
echo "Scenario 23 ready. Solve it now!"
EOF
chmod +x "${LAB_DIR}/q18-observability-logs/setup.sh"
cat << 'EOF' > "${LAB_DIR}/q18-observability-logs/check.sh"
#!/bin/bash
set -e
if [ ! -s /opt/errors.log ]; then
  echo "FAIL: /opt/errors.log does not exist or is empty"
  exit 1
fi
if ! grep -q "DB Connection Failed" /opt/errors.log; then
  echo "FAIL: /opt/errors.log does not contain extracted error logs"
  exit 1
fi
echo "PASS: Question 18 passed! Log errors extracted successfully."
EOF
chmod +x "${LAB_DIR}/q18-observability-logs/check.sh"
cat << 'EOF' > "${LAB_DIR}/q18-observability-logs/solve.sh"
#!/bin/bash
echo "1. kubectl top pods -n monitoring --sort-by=cpu --no-headers | head -1 | awk '{print \$1}' > /opt/high_cpu_pod.txt"
echo "2. kubectl logs faulty-backend -n default | grep '\[ERROR\]' > /opt/errors.log"
EOF
chmod +x "${LAB_DIR}/q18-observability-logs/solve.sh"
cat << 'EOF' > "${LAB_DIR}/q18-observability-logs/undo.sh"
