#!/bin/bash
set -e
if ! kubectl get pv app-pv &>/dev/null; then
  echo "FAIL: PV app-pv does not exist"
  exit 1
fi
PVC_STATUS=$(kubectl get pvc app-pvc -n default -o jsonpath='{.status.phase}')
if [ "$PVC_STATUS" != "Bound" ]; then
  echo "FAIL: PVC app-pvc status is '$PVC_STATUS' (expected Bound)"
  exit 1
fi
POD_STATUS=$(kubectl get pod app-storage -n default -o jsonpath='{.status.phase}')
if [ "$POD_STATUS" != "Running" ]; then
  echo "FAIL: Pod app-storage is '$POD_STATUS' (expected Running)"
  exit 1
fi
echo "PASS: Question 19 passed! Storage volume bound and mounted to pod."
EOF
